<?php
namespace App\Http\Controllers\Api\Admin;use App\Http\Controllers\Controller;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Illuminate\Validation\Rule;
class CampaignController extends Controller{public function index(){return DB::table('sale_campaigns')->orderByDesc('starts_at')->get()->map(function($c){$c->items=DB::table('sale_campaign_items as i')->join('product_variants as v','v.id','=','i.variant_id')->join('products as p','p.id','=','v.product_id')->where('i.campaign_id',$c->id)->select('i.*','v.sku','v.price','p.title')->get();return $c;});}public function store(Request $r){return $this->save($r);}public function update(Request $r,int $campaign){return $this->save($r,$campaign);}public function destroy(int $campaign){DB::table('sale_campaigns')->where('id',$campaign)->delete();return response()->noContent();}private function save(Request $r,?int $id=null){$data=$r->validate(['title'=>'required|string|max:150','slug'=>['required','alpha_dash',Rule::unique('sale_campaigns')->ignore($id)],'badge'=>'nullable|string|max:50','image'=>'nullable|string','starts_at'=>'required|date','ends_at'=>'required|date|after:starts_at','is_active'=>'sometimes|boolean','sort_order'=>'sometimes|integer|min:0','items'=>'required|array|min:1','items.*.variant_id'=>'required|distinct|exists:product_variants,id','items.*.sale_price'=>'required|integer|min:1','items.*.stock_limit'=>'nullable|integer|min:1']);$items=$data['items'];unset($data['items']);$campaign=DB::transaction(function()use($data,$items,$id){if($id){DB::table('sale_campaigns')->where('id',$id)->update($data+['updated_at'=>now()]);DB::table('sale_campaign_items')->where('campaign_id',$id)->delete();$campaign=$id;}else $campaign=DB::table('sale_campaigns')->insertGetId($data+['created_at'=>now(),'updated_at'=>now()]);foreach($items as $item)DB::table('sale_campaign_items')->insert($item+['campaign_id'=>$campaign,'created_at'=>now(),'updated_at'=>now()]);return $campaign;});return DB::table('sale_campaigns')->find($campaign);}}
